-- Name: google_reviews; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.google_reviews (
    review_id text NOT NULL,
    clinic_id uuid NOT NULL,
    source text,
    star_rating smallint,
    comment text,
    reviewer_name text,
    reviewer_photo text,
    reviewer_url text,
    is_anonymous boolean DEFAULT false,
    created_at_g timestamp with time zone,
    updated_at_g timestamp with time zone,
    last_synced_at timestamp with time zone DEFAULT now(),
    expires_at timestamp with time zone,
    CONSTRAINT google_reviews_source_check CHECK ((source = ANY (ARRAY['GBP'::text, 'PLACES'::text])))
);


ALTER TABLE public.google_reviews OWNER TO postgres;

--
-- Name: google_reviews_latest3; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.google_reviews_latest3 AS
 WITH ranked_reviews AS (
         SELECT google_reviews.review_id,
            google_reviews.clinic_id,
            google_reviews.source,
            google_reviews.star_rating,
            google_reviews.comment,
            google_reviews.reviewer_name,
            google_reviews.reviewer_photo,
            google_reviews.reviewer_url,
            google_reviews.is_anonymous,
            google_reviews.created_at_g,
            google_reviews.updated_at_g,
            google_reviews.last_synced_at,
            google_reviews.expires_at,
            row_number() OVER (PARTITION BY google_reviews.clinic_id ORDER BY google_reviews.created_at_g DESC) AS rn
           FROM public.google_reviews
          WHERE (google_reviews.expires_at > now())
        )
 SELECT review_id,
    clinic_id,
    source,
    star_rating,
    comment,
    reviewer_name,
    reviewer_photo,
    reviewer_url,
    is_anonymous,
    created_at_g
   FROM ranked_reviews
  WHERE (rn <= 3);


ALTER VIEW public.google_reviews_latest3 OWNER TO postgres;

