--
-- Name: plans Gli admin possono gestire i piani.; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Gli admin possono gestire i piani." ON public.plans USING ((( SELECT profiles.role
   FROM public.profiles
  WHERE (profiles.id = auth.uid())) = 'admin'::public.user_role));


--
-- Name: services_taxonomy Gli admin possono gestire la tassonomia.; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Gli admin possono gestire la tassonomia." ON public.services_taxonomy USING ((( SELECT profiles.role
   FROM public.profiles
  WHERE (profiles.id = auth.uid())) = 'admin'::public.user_role));


--
-- Name: clinics Gli admin possono gestire tutte le cliniche.; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Gli admin possono gestire tutte le cliniche." ON public.clinics USING ((( SELECT profiles.role
   FROM public.profiles
  WHERE (profiles.id = auth.uid())) = 'admin'::public.user_role));


--
-- Name: claims Gli admin possono gestire tutti i reclami.; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Gli admin possono gestire tutti i reclami." ON public.claims USING ((( SELECT profiles.role
   FROM public.profiles
  WHERE (profiles.id = auth.uid())) = 'admin'::public.user_role));


--
-- Name: subscriptions Gli admin possono vedere tutti gli abbonamenti.; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Gli admin possono vedere tutti gli abbonamenti." ON public.subscriptions FOR SELECT USING ((( SELECT profiles.role
   FROM public.profiles
  WHERE (profiles.id = auth.uid())) = 'admin'::public.user_role));


--
-- Name: profiles Gli utenti possono aggiornare il proprio profilo.; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Gli utenti possono aggiornare il proprio profilo." ON public.profiles FOR UPDATE USING ((auth.uid() = id));


--
-- Name: claims Gli utenti possono creare e vedere i propri reclami.; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Gli utenti possono creare e vedere i propri reclami." ON public.claims USING ((auth.uid() = user_id));


--
-- Name: profiles Gli utenti possono inserire il proprio profilo.; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Gli utenti possono inserire il proprio profilo." ON public.profiles FOR INSERT WITH CHECK ((auth.uid() = id));


--
-- Name: subscriptions Gli utenti possono vedere il proprio abbonamento.; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Gli utenti possono vedere il proprio abbonamento." ON public.subscriptions FOR SELECT USING ((auth.uid() = user_id));


--
-- Name: profiles Gli utenti possono vedere tutti i profili.; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Gli utenti possono vedere tutti i profili." ON public.profiles FOR SELECT USING (true);


--
-- Name: google_reviews_summary I riepiloghi delle recensioni sono visibili a tutti; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "I riepiloghi delle recensioni sono visibili a tutti" ON public.google_reviews_summary FOR SELECT USING (true);


--
-- Name: clinics I veterinari possono aggiornare la propria clinica.; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "I veterinari possono aggiornare la propria clinica." ON public.clinics FOR UPDATE USING (((auth.uid() = owner_id) AND (( SELECT profiles.role
   FROM public.profiles
  WHERE (profiles.id = auth.uid())) = 'veterinario'::public.user_role)));


--
-- Name: services_prices I veterinari possono gestire i prezzi della propria clinica.; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "I veterinari possono gestire i prezzi della propria clinica." ON public.services_prices USING ((EXISTS ( SELECT 1
   FROM public.clinics
  WHERE ((clinics.id = services_prices.clinic_id) AND (clinics.owner_id = auth.uid())))));


--
-- Name: clinics I veterinari possono inserire la propria clinica.; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "I veterinari possono inserire la propria clinica." ON public.clinics FOR INSERT WITH CHECK (((auth.uid() = owner_id) AND (( SELECT profiles.role
   FROM public.profiles
  WHERE (profiles.id = auth.uid())) = 'veterinario'::public.user_role)));


--
-- Name: clinics Le cliniche pubblicate sono visibili a tutti.; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Le cliniche pubblicate sono visibili a tutti." ON public.clinics FOR SELECT USING ((status = 'pubblicata'::public.clinic_status));


--
-- Name: google_reviews Le recensioni sono visibili a tutti; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Le recensioni sono visibili a tutti" ON public.google_reviews FOR SELECT USING (true);


--
-- Name: plans Tutti possono vedere i piani.; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Tutti possono vedere i piani." ON public.plans FOR SELECT USING (true);


